// Generated by scripts/db-pull.js. Column types drizzle-orm/mysql-core has no builder for.
const { customType } = require("drizzle-orm/mysql-core");

// Maps MySQL BLOB to a Node.js Buffer
const blob = customType({
	dataType() {
		return "blob";
	},
});

// Maps MySQL LONGBLOB to a Node.js Buffer
const longblob = customType({
	dataType() {
		return "longblob";
	},
});

module.exports = { blob, longblob };
